args.sparql:
SELECT ?paternal_grandfather ?paternal_grandfatherLabel WHERE {
  dbr:Rudolf_of_Żagań dbp:father ?father .
  ?father dbp:father ?paternal_grandfather .
  OPTIONAL {
    ?paternal_grandfather rdfs:label ?paternal_grandfatherLabel .
    FILTER (lang(?paternal_grandfatherLabel) = "en")
  }
}

